head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSecugrpID = "";
scwin.notiId;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        buttonSet.setSaveInfo(btn_save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_modify, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_delete, scwin.delete); // 삭제

        setInsertReadyStatus = "I";
        getId = $c.frame.path("../").fn_getId;
        scwin.notiId = getId();
        if (scwin.notiId !== "input") {
            buttonSet.setUpdateStatus();
            await scwin.read();
        } else {
            buttonSet.setInsertStatus();
            txb_user_nm.setValue(js_emp_nm);
            scwin.setDataHeader();
            await scwin.setSaveHeader();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40301.onpageload" });
    }
};

/**
 * @method
