/**
 * @method
 * @name grd_userlist_OnDblClick
 * @description grd_userlist 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_userlist_OnDblClick = function(row, colid) {
    try {
        if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            $c.elw.fn_filedown(dts_fileList.getCellData(row, "SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40301.grd_userlist_OnDblClick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        if (scwin.notiId === "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            // dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40301.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function() {
    try {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            if (scwin.notiId === "input") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                // dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
                file_name.setValue(inf_find.getValue());
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40301.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        dts_fileList.removeRow(dts_fileList.getRowPosition());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF40301.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
