    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF40301.btn_close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/ConsultationBookManagement.do",
        ref : "dts_readConsultationBook,dts_fileList",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "SAVE_EMP_NO", js_emp_no);
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "SPOT_ISU_TRD_MKT_TP_CD", js_market);
    if (edt_Date.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장일자"));
        edt_Date.focus();
        return;
    }
    if (txb_isur_cd.getValue() === "") {
        await $c.win.alert("[회사명]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    if (txb_doc_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_doc_title.focus();
        return;
    }
    let fileYn = "N";
    for (i = 1; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") !== "") {
            fileYn = "Y";
        }
    }
    if (fileYn === "N") {
        await $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    let rtn = confirm('상장알림내역을 등록 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ConsultationBookManagement.do",
            ref : "dts_consultationBook,dts_fileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    if (edt_Date.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "상장일자"));
        edt_Date.focus();
        return;
    }
    if (txb_isur_cd.getValue() === "") {
        await $c.win.alert("[회사명]을 선택해주세요.");
        txb_isur_cd.focus();
        return;
    }
    if (txb_doc_title.getValue() === "") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_doc_title.focus();
        return;
    }
    dts_fileList.setBroadcast(false);
    for (i = 0; i <= dts_fileList.getRowCount(); i++) {
        if (dts_fileList.getCellData(i, "fileInfo") === "" && dts_fileList.getCellData(i, "filename") === "") {
            dts_fileList.removeRow(i);
        }
    }
    dts_fileList.setBroadcast(true, true);
    if (dts_fileList.getRowCount() === 0) {
        await $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    let rtn = confirm('상장알림내역을 수정 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        const sbmOptions = {
            id : "sbm_trs_Update",
            action : "/ConsultationBookManagement.do",
            ref : "dts_readConsultationBook,dts_fileList",
            target : "trs_Update=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    let rtn = confirm('상장알림내역을 삭제 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {

        // dts_delConsultationBook.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
        dts_delConsultationBook.insertRow();
        dts_delConsultationBook.setCellData(1, "NOTI_ID", scwin.notiId);
        const sbmOptions = {
            id : "sbm_trs_Delete",
            action : "/ConsultationBookManagement.do",
            ref : "dts_delConsultationBook",
            target : "trs_Delete=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name setSaveHeader
 * @description CUD용 Header
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSaveHeader = async function() {
    // CUD용 Header
    const sbmOptions = {
        id : "sbm_dts_consultationBook",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_consultationBook=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_consultationBook.insertRow();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name filedown
 * @description 파일 다운로드
 * @param {*} attach_seq attach_seq
 * @returns {void}
 * @hidden N
 */
scwin.filedown = function(attach_seq) {
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF40301.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&file_id=" + scwin.notiId + "&attach_seq=" + attach_seq + "&gubun=5";
};

/**
 * @method
 * @name setDataHeader
 * @description set Data Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setDataHeader = function() {

    // dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    dts_consultationBook.setCellData(dts_consultationBook.getRowPosition(), "ISUR_CD", arrPar[0].ISUR_CD);
    txb_isur_cd.setValue(arrPar[0].COM_NM);
};
